#nullable enable // autogenerated

using MVZ2.GameContent.Areas;
using MVZ2.GameContent.Artifacts;
using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.maplewheel)]
    public class Maplewheel : DispenserFamily, IBeBlownBehaviour
    {
        public Maplewheel(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_MASK_FRIENDLY, IntegerOperator.BitOr, EntityCollisionHelper.MASK_PROJECTILE));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            ShootTick(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetAnimationFloat("SpinSpeed", GetSpinSpeed(entity));

            var spinSpeed = GetSpinSpeed(entity);
            var min = GetMinSpinSpeed(entity);
            spinSpeed = Mathf.Max(spinSpeed - SPIN_SPEED_FADE_SPEED, min);
            SetSpinSpeed(entity, spinSpeed);
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state != EntityCollisionHelper.STATE_ENTER)
                return;
            var entity = collision.Entity;
            var other = collision.Other;
            if (other.Type != EntityTypes.PROJECTILE)
                return;
            if (!entity.IsFriendly(other))
                return;
            if (other.SpawnerReference?.GetTarget(entity.Level) == entity && ProjectileCommonBehaviour.GetStartHitSpawnerProtectTimeout(other) > 0)
                return;
            if (!other.IsEntityOf(VanillaProjectileID.airSlash))
                return;
            BuffAirSlash(entity, other);
            SetMaxSpinSpeed(entity);
        }
        public override void OnShootTick(Entity entity)
        {
            base.OnShootTick(entity);
            SetMaxSpinSpeed(entity);
        }
        public static void BuffAirSlash(Entity entity, Entity airSlash)
        {
            var buff = airSlash.GetFirstBuff<AirSlashDamageUpBuff>();
            if (buff == null)
            {
                buff = airSlash.AddBuff<AirSlashDamageUpBuff>();
            }
            var damageUp = AirSlashDamageUpBuff.GetDamageUp(buff);
            if (damageUp < MAX_DAMAGE_UP)
            {
                damageUp += entity.GetDamage();
                damageUp = Mathf.Min(MAX_DAMAGE_UP, damageUp);
                AirSlashDamageUpBuff.SetDamageUp(buff, damageUp);
            }
        }
        public static float GetMinSpinSpeed(Entity entity)
        {
            if (entity.Level.AreaID == VanillaAreaID.ship || entity.Level.HasArtifact(VanillaArtifactID.galeLeaf))
            {
                return 1;
            }
            return 0;
        }
        public void BeBlown(Entity entity, Entity source)
        {
            SetMaxSpinSpeed(entity);
            if (entity.IsSecondsInterval(BLOWN_SHOOT_INTERVAL))
            {
                Shoot(entity);
            }
        }
        public static void SetMaxSpinSpeed(Entity entity) => SetSpinSpeed(entity, MAX_SPIN_SPEED);
        public static float GetSpinSpeed(Entity entity) => entity.GetBehaviourField<float>(PROP_SPIN_SPEED);
        public static void SetSpinSpeed(Entity entity, float value) => entity.SetBehaviourField(PROP_SPIN_SPEED, value);
        public const float MAX_DAMAGE_UP = 180;
        public const float MAX_SPIN_SPEED = 5f;
        public const float SPIN_SPEED_FADE_SPEED = 1 / 6f;
        public const float BLOWN_SHOOT_INTERVAL = 0.5f;
        public static readonly VanillaEntityPropertyMeta<float> PROP_SPIN_SPEED = new VanillaEntityPropertyMeta<float>("spin_speed");
    }
}
